for(const context of ['owner','template','design'])test('config and package callbacks cannot return after '+context+' A to B to A',async()=>withConfig(async r=>{const label=r.field('Texto del botón'),video=r.uploader('entry').onChange,calendar=r.aria('Mostrar Agendar evento'),remove=r.button('🗑️ Eliminar invitación permanentemente').props.onClick,original=clone(r.data());if(context==='owner'){await r.setData({id:IDS[1]});await r.setData({id:IDS[0]});}else if(context==='template'){await r.setData({template:'passport'});await r.setData({template:original.template});}else{await r.setConfig(config=>({...config,designKey:'qa-other'}));await r.setConfig(config=>({...config,designKey:original.config.designKey}));}const before=clone(r.data()),count=r.patches.length;edit(label,'QA obsolete');video('/qa-obsolete.mp4');edit(calendar,false);remove();await r.flush();assert.deepEqual(r.data(),before);assert.equal(r.patches.length,count);assert.equal(r.deletions.length,0);edit(r.field('Texto del botón'),'QA fresh');await r.flush();assert.equal(r.data().config.entry.label,'QA fresh');}));
