test('authoritative validity delegation survives same-owner template or history changes and rejects another owner before render',async()=>{for(const change of ['template','revision'])await withConfig(async r=>{const sync=r.props(childTypes.ValidityPanel)[0].onSync,fields=Object.freeze({validity_mode:'automatic',validity_extra_days:12,validity_revision:7,expires_at:'2027-06-14'});assert.equal(typeof sync,'function');if(change==='template')r.commitBeforeRender({template:'passport'});else r.editingRevision.current++;sync(fields);await r.flush();assert.equal(r.validity.length,1);assert.equal(r.validity[0],fields,'The authoritative fields must be forwarded exactly; Builder syncValidity owns revision ordering');assert.equal(r.patches.length,0);r.commitBeforeRender({id:IDS[1]});sync({...fields,validity_revision:8});await r.flush();assert.equal(r.validity.length,1,'A retained response cannot be delegated to another owner');assert.equal(r.patches.length,0);});});

