const deferred=()=>{let resolve;const promise=new Promise(done=>{resolve=done;});return{promise,resolve};};
const libraryTemplate=(id,name)=>({id,name,createdAt:1,layout:{version:2,basePreset:'qa-library',presetKey:'qa-library',blocks:[block('qa-template-content',{props:{text:'QA contenido '+id}})]},theme:{primary:'#224466'}});
const librarySection=(id,name)=>({id,name,createdAt:1,blocks:[block('qa-section-content',{props:{text:'QA sección '+id}})]});
test('a late initial template load cannot hide a more recent successful library save',async()=>{const initial=deferred(),saved=libraryTemplate('qa-saved-latest','QA Saved template latest unique'),old=libraryTemplate('qa-loaded-old','QA Loaded template old unique');await withBlocks(async r=>{r.press('+ Biblioteca');await r.flush();r.press('+ Guardar actual');await r.flush();assert.match(normal(r.current()),/QA Saved template latest unique/);initial.resolve([old]);await r.flush();assert.match(normal(r.current()),/QA Saved template latest unique/);assert.doesNotMatch(normal(r.current()),/QA Loaded template old unique/);assert.equal(r.calls().filter(call=>call.kind==='template-save').length,1);assert.equal(r.patches.length,0);},{selected:'',prompt:()=>saved.name,operations:{listTemplates:()=>initial.promise,saveTemplate:()=>[saved]}});});
test('initial templates remain available while an earlier-started save is still pending',async()=>{const initial=deferred(),save=deferred(),loaded=libraryTemplate('qa-initial-available','QA Initial load available during save unique'),saved=libraryTemplate('qa-save-complete','QA Save completed after initial unique');await withBlocks(async r=>{r.press('+ Biblioteca');await r.flush();r.press('+ Guardar actual');await r.flush();assert.equal(r.calls().filter(call=>call.kind==='template-save').length,1);initial.resolve([loaded]);await r.flush();assert.match(normal(r.current()),/QA Initial load available during save unique/);assert.ok(r.button('Aplicar'),'Loading the initial list must expose usable existing templates while save is pending');assert.doesNotMatch(normal(r.current()),/QA Save completed after initial unique/);save.resolve([loaded,saved]);await r.flush();assert.match(normal(r.current()),/QA Initial load available during save unique/);assert.match(normal(r.current()),/QA Save completed after initial unique/);assert.equal(r.patches.length,0);},{selected:'',prompt:()=>saved.name,operations:{listTemplates:()=>initial.promise,saveTemplate:()=>save.promise}});});
test('template and section library operations do not discard each others independent initial responses',async()=>{const sectionLoad=deferred(),cloudSection=librarySection('qa-cloud-section','QA Cloud section independent unique'),savedTemplate=libraryTemplate('qa-local-template','QA Local template independent unique');await withBlocks(async r=>{r.press('+ Biblioteca');await r.flush();r.press('+ Guardar actual');await r.flush();sectionLoad.resolve({sections:[cloudSection],cloud:true});await r.flush();assert.match(normal(r.current()),/QA Local template independent unique/);assert.match(normal(r.current()),/QA Cloud section independent unique/);},{selected:'',prompt:()=>savedTemplate.name,operations:{hydrateSections:()=>sectionLoad.promise,saveTemplate:()=>[savedTemplate]}});const templateLoad=deferred(),cloudTemplate=libraryTemplate('qa-cloud-template','QA Cloud template independent unique'),savedSection=librarySection('qa-local-section','QA Local section independent unique');await withBlocks(async r=>{r.press('Guardar como sección reutilizable');await r.flush();templateLoad.resolve([cloudTemplate]);await r.flush();await r.select('');r.press('+ Biblioteca');await r.flush();assert.match(normal(r.current()),/QA Local section independent unique/);assert.match(normal(r.current()),/QA Cloud template independent unique/);},{prompt:()=>savedSection.name,operations:{listTemplates:()=>templateLoad.promise,saveSection:()=>[savedSection]}});});
test('a pending template save does not block applying another template and its stale completion is ignored',async()=>{const pending=deferred(),available=libraryTemplate('qa-template-available','QA Available template unique'),obsolete=libraryTemplate('qa-obsolete-save','QA Obsolete saved template unique');await withBlocks(async r=>{r.press('+ Biblioteca');await r.flush();r.press('+ Guardar actual');await r.flush();assert.equal(r.calls().filter(call=>call.kind==='template-save').length,1);r.press('Aplicar');await r.flush();assert.equal(r.data().config.layout.presetKey,'qa-library');assert.equal(r.blocks()[0].props.text,'QA contenido qa-template-available');assert.equal(r.patches.length,1);pending.resolve([obsolete]);await r.flush();assert.doesNotMatch(normal(r.current()),/QA Obsolete saved template unique/);assert.match(normal(r.current()),/QA Available template unique/);assert.equal(r.blocks()[0].props.text,'QA contenido qa-template-available');},{selected:'',libraries:{templates:[available],sections:[]},prompt:()=>obsolete.name,operations:{saveTemplate:()=>pending.promise}});});
test('newer library requests remain actionable and superseded or invalid-context completions are not adopted',async()=>{for(const invalidation of ['owner','unmount']){const first=deferred(),second=deferred(),third=deferred(),requests=[first,second,third],initial=libraryTemplate('qa-initial','QA Initial template unique'),old=libraryTemplate('qa-old-response','QA Superseded response unique'),latest=libraryTemplate('qa-new-response','QA Current response unique'),stale=libraryTemplate('qa-context-response','QA Invalid context response unique');let request=0;await withBlocks(async r=>{r.press('+ Biblioteca');await r.flush();r.press('+ Guardar actual');r.press('+ Guardar actual');await r.flush();assert.equal(r.calls().filter(call=>call.kind==='template-save').length,2,'A pending request must not lock later library actions');first.resolve([old]);await r.flush();assert.doesNotMatch(normal(r.current()),/QA Superseded response unique/);assert.match(normal(r.current()),/QA Initial template unique/);second.resolve([latest]);await r.flush();assert.match(normal(r.current()),/QA Current response unique/);r.press('+ Guardar actual');await r.flush();assert.equal(request,3);if(invalidation==='owner')await r.setData({id:IDS[1]});else r.unmount();const count=r.lateWrites();third.resolve([stale]);await r.flush();assert.doesNotMatch(normal(r.current()),/QA Invalid context response unique/);assert.equal(r.lateWrites(),count);assert.equal(r.patches.length,0);},{selected:'',libraries:{templates:[initial],sections:[]},prompt:()=> 'QA Library deferred save',operations:{saveTemplate:()=>requests[request++].promise}});}});
test('parent wiring passes its existing current draft and revision to both corrected panels',()=>{const relative='src/components/admin/builder/InvitationBuilder.tsx',ast=ts.createSourceFile(relative,sourceFor(relative),ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX),found=[];const visit=node=>{if((ts.isJsxOpeningElement(node)||ts.isJsxSelfClosingElement(node))&&['ConfigPanel','BlockEditorPanel'].includes(node.tagName.getText(ast))){const props={panel:node.tagName.getText(ast)};for(const attribute of node.attributes.properties)if(ts.isJsxAttribute(attribute)&&attribute.initializer&&ts.isJsxExpression(attribute.initializer))props[attribute.name.getText(ast)]=attribute.initializer.expression?.getText(ast);found.push(props);}ts.forEachChild(node,visit);};visit(ast);for(const panel of ['ConfigPanel','BlockEditorPanel'])assert.ok(found.some(props=>props.panel===panel&&props.editingRevision==='blockMediaRevision'&&props.draftSource==='dataRef'),panel+' requires both real Builder refs');});
